rules.pseudocode:
for (j = 0; j < (int)runBars; ++j)
  if (!(emaFast[j] < emaSlow[j] && low[j] > emaSlow[j])) return false;   // emaFast/emaSlow: XAverage series variables
return true;

for (j = 0; j < (int)runBars; ++j)
  if (!(low[j] <= min(emaFast[j], emaSlow[j]) && high[j] >= max(emaFast[j], emaSlow[j]))) return false;
return true;

// long side (mirror of the note's short):
long = el_lt(emaF, emaS) && el_lt(emaF, emaF[X]) && el_lt(emaS, emaS[X])
       && el_lt(emaS - emaF, emaS[X] - emaF[X]);

dLong  = average(close - ema, longWindow) / atr;
dShort = average(close - ema, shortWindow) / atr;
long = el_ge(dLong, minLongAtr) && el_le(absvalue(dShort), maxShortAtr);

if (el_le(low[0], ema) && el_ge(high[0], ema)) {
    if (el_gt(minlist(open[0], close[0]), ema)) upRun = upRun + 1; else upRun = 0;
    if (el_lt(maxlist(open[0], close[0]), ema)) dnRun = dnRun + 1; else dnRun = 0;
}
long = el_ge(upRun, touchCount);

touch = el_le(low[0], ema) && el_ge(high[0], ema);
// persistent: gaps[] = bar counts between successive touches, newest-first; curGap = bars since last touch
long = touch && haveN && el_ge(curGap, K * meanOf(gaps, N)) && el_lt(high[1], ema[1]);

top = average(maxlist(open, close), N); bot = average(minlist(open, close), N);
mid = (top + bot) / 2; w = top - bot;
long = el_gt(close[0], mid + X * w);

ok = true;
for (i = 0; i < X; ++i) if (!el_gt(close[i], ma[i])) ok = false;
for (i = X; i < X + Y; ++i) if (!el_lt(close[i], ma[i])) ok = false;
long = ok;
